def slug(text: str) -> str:
    text = text.lower().replace("&", " and ")
    text = re.sub(r"[^a-z0-9]+", "-", text).strip("-")
    return text[:92]


def bands_for(grades=None, levels=None):
    grades = grades or []
    levels = levels or []
    bands=[]
    nums=[]
    for g in grades:
        m=re.search(r"\d+", str(g))
        if m: nums.append(int(m.group()))
    if any(n <= 6 for n in nums): bands.append("kids")
    if any(4 <= n <= 8 for n in nums): bands.append("juniors")
    if any(7 <= n <= 12 for n in nums): bands.append("teens")
    if any(11 <= n <= 12 for n in nums): bands.append("grads")
    if "open" in levels and not bands: bands.append("club")
    return list(dict.fromkeys(bands))


def academic_bands(subjects, levels):
    out=[]
    s=" ".join(subjects).lower()
    if any(x in levels for x in ["undergraduate","graduate","postdoctoral","faculty","professional","educator"]): out.append("university")
    if "philosophy" in s or "ethics" in s or "logic" in s: out.append("philosophy")
    if any(x in s for x in ["history","humanities","literature","writing","archaeology","oral history","public history"]): out.append("humanities")
    return list(dict.fromkeys(out))


def iso_date(date: str, timezone: str, exact_time: str | None = None) -> str:
    if "T" in date: return date
    if exact_time:
        return f"{date}T{exact_time}"
    # Midnight carries the stated local date; timezone field preserves the governing zone.
    offset = "-04:00" if timezone in {"America/Toronto","America/New_York"} and date[5:7] in {"04","05","06","07","08","09","10"} else "-05:00" if timezone in {"America/Toronto","America/New_York"} else "Z"
    return f"{date}T00:00:00{offset}"


def add(*, title, date, source_url, set_name, description, organizer=None,
        end_date=None, exact_time=None, timezone="America/Toronto", type="contest",
        secondary_types=None, record_kind="opportunity", status="confirmed",
        q=None, date_precision=None, time_precision=None, city="Online", province="",
        country="Global", corridor="online-global", grades=None, ages=None, levels=None,
        subjects=None, genres=None, eligibility="Worldwide", opportunity_kind=None,
        topics=None, tags=None, source_name=None, source_language="en", source_languages=None,
        recurrence=None, deadline_confidence=None, parent_id=None, event_family=None,
        attendance=True, speaker=None, venue=None, confidence=None, merge_titles=None,
        merge_ids=None, additional=None, id=None, lifecycle=None):
    grades=grades or []
    levels=levels or []
    subjects=subjects or []
    genres=genres or []
    topics=topics or []
    tags=tags or []
    q=list(q or [])
    exact = exact_time is not None or "T" in date
    if status == "confirmed" and not exact and record_kind in {"opportunity","event"}:
        # A date can be confirmed while the time remains unpublished. Canonical status stays qualified.
        status="unconfirmed"
        q=list(dict.fromkeys(q+["time-unconfirmed"]))
    if status == "unconfirmed" and not q:
        q=["details-unconfirmed"]
    if time_precision is None:
        time_precision="exact" if exact else "unknown"
    if time_precision == "unknown" and "time-unconfirmed" not in q:
        q.append("time-unconfirmed")
    if status == "confirmed": q=[]
    date_precision = date_precision or ("exact" if exact or not any(x in q for x in ["date-unconfirmed","current-edition-unconfirmed"]) else "estimated")
    rid=id or slug(title)
    if any(r.get("id")==rid for r in records):
        rid=f"{rid}-{slug(date)[:12]}"
    dt=iso_date(date,timezone,exact_time)
    ed=iso_date(end_date,timezone) if end_date else None
    age_parts=[]
    if grades: age_parts.append(", ".join(grades))
    if ages: age_parts.append(ages)
    if levels: age_parts.append(", ".join(levels))
    age_band="; ".join(age_parts) or "Eligibility described by organizer"
    rec={
        "id":rid,
        "date":dt,
        "end_date":ed,
        "title":title,
        "type":type,
        "secondary_types":secondary_types or [],
        "speaker_or_director":speaker or organizer,
        "organizer":organizer,
        "venue":venue or ("Online / organizer website" if city=="Online" else city),
        "source_url":source_url,
        "source_id":"manual-curated" if source_url.find("soulpepper.ca")<0 else "soulpepper",
        "source_name":source_name or organizer or title,
        "description":description,
        "raw_excerpt":description,
        "age_band":age_band,
        "exact_grades":grades,
        "age_range":ages,
        "education_levels":levels,
        "writing_bands":bands_for(grades,levels) if any(x in " ".join(subjects).lower() for x in ["writing","literature","poetry","translation","playwriting","journalism"]) else [],
        "academic_bands":academic_bands(subjects,levels),
        "subjects":subjects,
        "genres":genres,
        "eligibility_region":eligibility,
        "opportunity_kind":opportunity_kind or type,
        "topics":list(dict.fromkeys(topics+subjects)),
        "tags":list(dict.fromkeys(tags+grades+levels)),
        "parent_id":parent_id,
        "is_parent_festival": record_kind in {"series","festival"},
        "attendance_confirmed":attendance,
        "confidence":confidence if confidence is not None else (100 if status=="confirmed" else 82),
        "record_kind":record_kind,
        "date_precision":date_precision,
        "time_precision":time_precision,
        "deadline_confidence":deadline_confidence or ("confirmed-exact" if status=="confirmed" else "qualified"),
        "source_notes":f"Set {set_name} public-source research synthesis; checked 2026-08-13. {('Current edition/date remains qualified.' if status=='unconfirmed' else 'Official or institutional source used.')}",
        "recurrence_note":recurrence,
        "source_quality":"official-or-institutional",
        "source_language":source_language,
        "source_languages":source_languages or [source_language],
        "source_language_method":"source-declared-or-page-language",
        "platform_adapter":"manual",
        "first_seen_at":CHECKED,
        "last_checked_at":CHECKED,
        "scraped_at":CHECKED,
        "lifecycle_status":lifecycle or ("archived" if dt[:10] < "2026-08-13" else "active"),
        "city":city,
        "province":province,
        "country":country,
        "corridor_zone":corridor,
        "timezone":timezone,
        "confirmation_status":status,
        "qualification_reasons":q,
        "legacy_ids":[],
        "missing_count":0,
        "event_family":event_family or set_name,
        "research_set":set_name,
        "research_batch":BATCH,
        "_src":BATCH,
        "_upsert_batches":[BATCH],
        "merge_titles":merge_titles or [],
        "merge_ids":merge_ids or [],
    }
    if additional: rec.update(additional)
    records.append(rec)
    return rid


def watch(*, marker, reasons=None, **kwargs):
    return add(date=marker, status="unconfirmed", q=(reasons or ["current-edition-unconfirmed","date-unconfirmed","time-unconfirmed"]), date_precision="estimated", time_precision="unknown", deadline_confidence="annual-watch", **kwargs)


def exclude(title, reason, source_url=None, set_name="Cross-set exclusions"):
    exclusions.append({"title":title,"reason":reason,"source_url":source_url,"research_set":set_name,"checked_at":CHECKED})

