# Build deterministic ledger.
ids=[r["id"] for r in records]
if len(ids)!=len(set(ids)):
    dup=sorted({x for x in ids if ids.count(x)>1})
    raise SystemExit(f"duplicate generated ids: {dup}")
records.sort(key=lambda r:(r["date"],r["title"],r["id"]))
payload={
    "schema":"polymythcal-research-integration-ledger-v1",
    "batch":BATCH,
    "generated_at":CHECKED,
    "scope":[S1,S2,S3,SC,MED],
    "record_count":len(records),
    "exclusion_count":len(exclusions),
    "records":records,
    "exclusions":sorted(exclusions,key=lambda x:(x["research_set"],x["title"])),
}
raw=(json.dumps(payload,ensure_ascii=False,indent=2)+"\n").encode()
payload["content_sha256_without_self_hash"]=hashlib.sha256(raw).hexdigest()
OUT.write_text(json.dumps(payload,ensure_ascii=False,indent=2)+"\n",encoding="utf-8")
print(json.dumps({"output":str(OUT),"records":len(records),"exclusions":len(exclusions)},indent=2))
